// A minimal vertical stack: shows what each pass is responsible for.
public class SimpleStackPanel : Panel
{
    protected override Size MeasureOverride(Size available)
    {
        double width = 0, height = 0;
        foreach (UIElement child in InternalChildren)
        {
            child.Measure(new Size(available.Width, double.PositiveInfinity)); // "how big do you want to be?"
            width = Math.Max(width, child.DesiredSize.Width);
            height += child.DesiredSize.Height;
        }
        return new Size(width, height);   // becomes this panel's DesiredSize
    }

    protected override Size ArrangeOverride(Size finalSize)
    {
        double y = 0;
        foreach (UIElement child in InternalChildren)
        {
            child.Arrange(new Rect(0, y, finalSize.Width, child.DesiredSize.Height)); // "here is your slot"
            y += child.DesiredSize.Height;
        }
        return finalSize;
    }
}

// Find the first descendant of type T in the visual tree (e.g. the ScrollViewer inside a ListBox).
public static T? FindVisualChild<T>(DependencyObject parent) where T : DependencyObject
{
    for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
    {
        var child = VisualTreeHelper.GetChild(parent, i);
        if (child is T match) return match;
        var deeper = FindVisualChild<T>(child);
        if (deeper != null) return deeper;
    }
    return null;
}

