// <TextBox local:TextBoxBehavior.SelectAllOnFocus="True" />
public static class TextBoxBehavior
{
    public static readonly DependencyProperty SelectAllOnFocusProperty =
        DependencyProperty.RegisterAttached(
            "SelectAllOnFocus", typeof(bool), typeof(TextBoxBehavior),
            new PropertyMetadata(false, OnSelectAllOnFocusChanged));

    public static bool GetSelectAllOnFocus(DependencyObject d) => (bool)d.GetValue(SelectAllOnFocusProperty);
    public static void SetSelectAllOnFocus(DependencyObject d, bool value) => d.SetValue(SelectAllOnFocusProperty, value);

    // The callback gets the element the property was set on — attach/detach behaviour here.
    private static void OnSelectAllOnFocusChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is not TextBox box) return;
        box.GotKeyboardFocus -= SelectAll;
        if ((bool)e.NewValue) box.GotKeyboardFocus += SelectAll;
    }

    private static void SelectAll(object sender, KeyboardFocusChangedEventArgs e) => ((TextBox)sender).SelectAll();
}

public class Gauge : Control
{
    public static readonly DependencyProperty ValueProperty = DependencyProperty.Register(
        nameof(Value), typeof(double), typeof(Gauge),
        new FrameworkPropertyMetadata(0.0, propertyChangedCallback: null, coerceValueCallback: CoerceToRange),
        validateValueCallback: IsFinite);                       // static rule, no instance

    public static readonly DependencyProperty MaximumProperty = DependencyProperty.Register(
        nameof(Maximum), typeof(double), typeof(Gauge),
        new FrameworkPropertyMetadata(100.0, OnMaximumChanged), IsFinite);

    public double Value { get => (double)GetValue(ValueProperty); set => SetValue(ValueProperty, value); }
    public double Maximum { get => (double)GetValue(MaximumProperty); set => SetValue(MaximumProperty, value); }

    private static bool IsFinite(object v) => double.IsFinite((double)v);   // false => the set throws (.NET Core 2.1+ API)

    private static object CoerceToRange(DependencyObject d, object baseValue)
    {
        var g = (Gauge)d;
        return Math.Clamp((double)baseValue, 0, g.Maximum);              // instance-aware adjustment
    }

    private static void OnMaximumChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
        => d.CoerceValue(ValueProperty);                                // re-check Value against the new limit
}

