[ValueConversion(typeof(decimal), typeof(Brush))]
public sealed class BalanceToBrushConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        => value is decimal d
            ? (d < 0 ? Brushes.Firebrick : Brushes.SeaGreen)
            : DependencyProperty.UnsetValue;            // not a decimal: use FallbackValue / default

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        => Binding.DoNothing;                           // one-way only: never push back
}

public sealed class AllFilledConverter : IMultiValueConverter
{
    // values[i] matches the i-th <Binding> inside the <MultiBinding>
    public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
        => values.All(v => v is string s && !string.IsNullOrWhiteSpace(s));

    public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
        => throw new NotSupportedException();
}

