public class ExpenseViewModel : ViewModelBase, INotifyDataErrorInfo
{
    private readonly Dictionary<string, List<string>> _errors = new();
    private decimal _amount;

    public decimal Amount
    {
        get => _amount;
        set { SetProperty(ref _amount, value); Validate(nameof(Amount), value > 0, "Amount must be greater than 0."); }
    }

    public bool HasErrors => _errors.Count > 0;
    public event EventHandler<DataErrorsChangedEventArgs>? ErrorsChanged;

    public IEnumerable GetErrors(string? propertyName)
        => propertyName != null && _errors.TryGetValue(propertyName, out var list) ? list : Array.Empty<string>();

    private void Validate(string property, bool isValid, string message)
    {
        if (isValid) _errors.Remove(property);
        else _errors[property] = new List<string> { message };
        ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(property)); // UI re-queries GetErrors
        OnPropertyChanged(nameof(HasErrors));
    }
}

