// Themes/Light.xaml and Themes/Dark.xaml both define: <SolidColorBrush x:Key="WindowBackground" ... />
// Views use: Background="{DynamicResource WindowBackground}"
public static class ThemeSwitcher
{
    public static void Apply(string theme)   // "Light" or "Dark"
    {
        var dictionaries = Application.Current.Resources.MergedDictionaries;
        var old = dictionaries.FirstOrDefault(d => d.Source?.OriginalString.StartsWith("Themes/") == true);
        if (old != null) dictionaries.Remove(old);

        dictionaries.Add(new ResourceDictionary { Source = new Uri($"Themes/{theme}.xaml", UriKind.Relative) });
        // Every {DynamicResource WindowBackground} re-resolves; {StaticResource ...} users would not change.
    }
}

[TemplatePart(Name = PartTrack, Type = typeof(FrameworkElement))]
public class Rating : Control
{
    private const string PartTrack = "PART_Track";
    private FrameworkElement? _track;

    static Rating()
    {
        // look for the default style keyed by typeof(Rating) in Themes/Generic.xaml
        DefaultStyleKeyProperty.OverrideMetadata(typeof(Rating), new FrameworkPropertyMetadata(typeof(Rating)));
    }

    public static readonly DependencyProperty ValueProperty = DependencyProperty.Register(
        nameof(Value), typeof(int), typeof(Rating),
        new FrameworkPropertyMetadata(0, FrameworkPropertyMetadataOptions.BindsTwoWayByDefault));

    public int Value { get => (int)GetValue(ValueProperty); set => SetValue(ValueProperty, value); }

    public override void OnApplyTemplate()
    {
        base.OnApplyTemplate();
        if (_track != null) _track.MouseLeftButtonUp -= OnTrackClicked;   // template may be swapped

        _track = GetTemplateChild(PartTrack) as FrameworkElement;          // null is allowed: degrade gracefully
        if (_track != null) _track.MouseLeftButtonUp += OnTrackClicked;
    }

    private void OnTrackClicked(object sender, MouseButtonEventArgs e)
    {
        var x = e.GetPosition(_track).X;
        SetCurrentValue(ValueProperty, (int)Math.Ceiling(x / _track!.ActualWidth * 5)); // keeps consumer bindings
    }
}

