        builder.Services.AddHostedService<AutoSaveService>();
        builder.Services.Configure<AppSettings>(builder.Configuration.GetSection("App"));
        _host = builder.Build();
    }

    protected override async void OnStartup(StartupEventArgs e)
    {
        await _host.StartAsync();                                // starts hosted services
        var window = _host.Services.GetRequiredService<MainWindow>(); // ctor(MainViewModel vm) sets DataContext
        window.Show();
        base.OnStartup(e);
    }

    protected override void OnExit(ExitEventArgs e)
    {
        // Bounded, synchronous stop: hosted services get the stopping token and singletons are disposed.
        // Keep hosted services off the UI SynchronizationContext (ConfigureAwait(false) / Task.Run inside
        // ExecuteAsync) so this wait can't deadlock the UI thread.
        _host.StopAsync(TimeSpan.FromSeconds(5)).GetAwaiter().GetResult();
        _host.Dispose();
        base.OnExit(e);
    }
}

