[RelayCommand(IncludeCancelCommand = true)]
private async Task ImportAsync(CancellationToken token)
{
    var progress = new Progress<int>(p => ProgressPercent = p);     // created on UI thread → reports on UI thread

    var lines = await File.ReadAllLinesAsync(FilePath, token);      // I/O: no Task.Run needed
    var rows = await Task.Run(() => Parse(lines, progress, token), token); // CPU work off the UI thread

    Rows.Clear();                                                   // back on the UI thread: safe
    foreach (var r in rows) Rows.Add(r);
}

private static List<Row> Parse(string[] lines, IProgress<int> progress, CancellationToken token)
{
    var result = new List<Row>(lines.Length);
    for (int i = 0; i < lines.Length; i++)
    {
        token.ThrowIfCancellationRequested();
        result.Add(Row.Parse(lines[i]));
        if (i % 500 == 0) progress.Report(i * 100 / lines.Length);
    }
    return result;
}

